import 'package:cloud_firestore/cloud_firestore.dart';
import '../models/consultation_model.dart';
class ConsultationRepository { ConsultationRepository(this._db); final FirebaseFirestore _db; Stream<List<ConsultationModel>> watchForUser(String userId,{required bool isAdvisor})=>_db.collection('consultations').where(isAdvisor?'advisorId':'studentId',isEqualTo:userId).orderBy('createdAt',descending:true).snapshots().map((snapshot)=>snapshot.docs.map(ConsultationModel.fromFirestore).toList()); Future<void> create(ConsultationModel model)=>_db.collection('consultations').doc(model.id).set(model.toMap()); Future<void> updateStatus(String id,ConsultationStatus status,{String? conversationId})=>_db.collection('consultations').doc(id).update({'status':status.name,'conversationId':conversationId,'updatedAt':FieldValue.serverTimestamp()}); }
